"use strict";(globalThis.webpackChunkUserDocumentation=globalThis.webpackChunkUserDocumentation||[]).push([[5709],{2689(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"infomeka-2026","metadata":{"permalink":"/en/blog/infomeka-2026","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-11-05-infomeka-2026.md","source":"@site/blog/2026-11-05-infomeka-2026.md","title":"NumaHOP et Omeka","description":"Retrouvez NumaHOP \xe0 l\'Infomeka du 20 novembre 2026, organis\xe9 par","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":false,"label":"Omeka","permalink":"/en/blog/tags/omeka"},{"inline":false,"label":"Action de formation","permalink":"/en/blog/tags/formation"}],"hasTruncateMarker":false,"authors":[{"name":"Nathalie Pilet","title":"Biblioth\xe8que universitaire des langues et civilisations","page":{"permalink":"/en/blog/authors/npilet"},"imageURL":"/en/img/photos/npilet.jpg","key":"npilet"},{"name":"Oriane Boissel","title":"Universit\xe9 Paris Saclay","page":{"permalink":"/en/blog/authors/oboissel"},"imageURL":"/en/img/photos/oboissel.jpg","key":"oboissel"}],"frontMatter":{"slug":"infomeka-2026","title":"NumaHOP et Omeka","date":"2026-11-05T00:00:00.000Z","tags":["omeka","formation"],"authors":["npilet","oboissel"]},"unlisted":false,"nextItem":{"title":"Le Campus Condorcet accueille la Journ\xe9e professionnelle 2026","permalink":"/en/blog/journees-2026"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nRetrouvez NumaHOP \xe0 l\'Infomeka du 20 novembre 2026, organis\xe9 par\\nl\'AUFO (Association des Utilisateurs Francophones d\'Omeka), pour d\xe9couvrir comment importer ses donn\xe9es de NumaHOP vers\\nOmeka S avec CSV Import.\\n\\nPour plus d\'information, consultez le <Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [site officiel de l\'AUFO](https://omeka.fr)."},{"id":"journees-2026","metadata":{"permalink":"/en/blog/journees-2026","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-09-01-journees-2026.md","source":"@site/blog/2026-09-01-journees-2026.md","title":"Le Campus Condorcet accueille la Journ\xe9e professionnelle 2026","description":"L\u2019association NumaHOP a le plaisir de vous convier \xe0 sa Journ\xe9e professionnelle 2026, ouverte \xe0 toutes et tous et gratuites sur inscription. Cette ann\xe9e sera l\u2019occasion de dresser un premier bilan sur les \xe9volutions r\xe9centes et \xe0 venir port\xe9es par l\u2019association, ainsi que sur l\u2019\xe9largissement de la communaut\xe9 des utilisateurs.","date":"2026-09-01T00:00:00.000Z","tags":[{"inline":false,"label":"Journ\xe9es professionnelles","permalink":"/en/blog/tags/journeespro"},{"inline":false,"label":"Humath\xe8que Condorcet","permalink":"/en/blog/tags/humatheque"}],"hasTruncateMarker":true,"authors":[{"name":"Fran\xe7ois Gandolfi","title":"Humath\xe8que Condorcet","page":{"permalink":"/en/blog/authors/fgandolfi"},"imageURL":"/en/img/photos/fgandolfi.jpg","key":"fgandolfi"}],"frontMatter":{"slug":"journees-2026","title":"Le Campus Condorcet accueille la Journ\xe9e professionnelle 2026","date":"2026-09-01T00:00:00.000Z","tags":["journeespro","humatheque"],"authors":"fgandolfi"},"unlisted":false,"prevItem":{"title":"NumaHOP et Omeka","permalink":"/en/blog/infomeka-2026"},"nextItem":{"title":"Conf\xe9rence annuelle de la Ligue des Biblioth\xe8ques Europ\xe9ennes de Recherche","permalink":"/en/blog/liber-trondheim"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nL\u2019association NumaHOP a le plaisir de vous convier \xe0 sa **Journ\xe9e professionnelle 2026**, ouverte \xe0 toutes et tous et gratuites sur inscription. Cette ann\xe9e sera l\u2019occasion de dresser un premier bilan sur les \xe9volutions r\xe9centes et \xe0 venir port\xe9es par l\u2019association, ainsi que sur l\u2019\xe9largissement de la communaut\xe9 des utilisateurs.\\n\\n<Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [Site officiel des Journ\xe9es Numahop 2026](https://numahop2026.sciencesconf.org/).\\n\\n\x3c!-- truncate --\x3e\\n\\n### Pourquoi participer ?\\n\\n- D\xe9couvrir les derni\xe8res actualit\xe9s de l\'association.\\n- \xc9changer avec la communaut\xe9 des utilisateurs et des prestataires.\\n- Contribuer aux ateliers pratiques et \xe0 la gouvernance du projet.\\n- S\u2019initier au bac \xe0 sable et \xe0 la documentation utilisateur.\\n\\n ### Informations pratiques\\n\\nLa Journ\xe9e professionnelle NumaHOP aura lieu le **Jeudi 19 novembre 2026** sur le **Campus Condorcet** (Aubervilliers). Les conf\xe9rence de la matin\xe9e se tiendront au Centre des Colloques, Auditorium 150, les ateliers de l\'apr\xe8s-midi \xe0 l\'OpenSpace de l\'Humath\xe8que. Le dejeuner sera offert par l\'Association NumaHOP \xe0 12h30 (Forum de l\u2019Humath\xe8que).\\n\\n- **Acc\xe8s** : Campus Condorcet, 10 cours des Humanit\xe9s (m\xe9tro Front Populaire, ligne 12 / RER B La Plaine - Stade de France).\\n- **Mat\xe9riel** : Pr\xe9voyez un ordinateur portable pour les ateliers.\\n- **Contact** : Pour toute question, \xe9crivez au [Bureau de l\u2019Association NumaHOP <Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} />](mailto:association-numahop@sorbonne-nouvelle.fr?).\\n\\nRetrouvez le programme d\xe9taill\xe9 sur le <Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [site officiel des Journ\xe9es Numahop 2026](https://numahop2026.sciencesconf.org/)."},{"id":"liber-trondheim","metadata":{"permalink":"/en/blog/liber-trondheim","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-07-10-liber-trondheim.md","source":"@site/blog/2026-07-10-liber-trondheim.md","title":"Conf\xe9rence annuelle de la Ligue des Biblioth\xe8ques Europ\xe9ennes de Recherche","description":"Olesea Dubois (Sciences Po Paris) et Vincent Tardif (ENS paris) ont eu le plaisir de pr\xe9senter NumaHOP aux Journ\xe9es LIBER 2026 qui ont r\xe9uni une large communaut\xe9 europ\xe9enne de biblioth\xe8ques de recherche autour des enjeux strat\xe9giques li\xe9s aux infrastructures num\xe9riques et \xe0 la gestion des collections et \xe0 la science ouverte. L\'\xe9dition de cette ann\xe9e \xe0 particuli\xe8rement mis en avant les outils permettant de renforcer la r\xe9silience des biblioth\xe8ques face aux \xe9volutions technologiques rapides ainsi que les solutions collaboratives.","date":"2026-07-10T00:00:00.000Z","tags":[{"inline":false,"label":"S\xe9minaires & Conf\xe9rences","permalink":"/en/blog/tags/conf"}],"hasTruncateMarker":true,"authors":[{"name":"Vincent Tardif","title":"Biblioth\xe8que de l\'ENS","page":{"permalink":"/en/blog/authors/vtardif"},"imageURL":"/en/img/photos/vtardif.jpg","key":"vtardif"},{"name":"Olesea Dubois","title":"Sciences Po Paris","page":{"permalink":"/en/blog/authors/odubois"},"imageURL":"/en/img/photos/odubois.jpg","key":"odubois"}],"frontMatter":{"slug":"liber-trondheim","title":"Conf\xe9rence annuelle de la Ligue des Biblioth\xe8ques Europ\xe9ennes de Recherche","date":"2026-07-10T00:00:00.000Z","tags":["conf"],"authors":["vtardif","odubois"]},"unlisted":false,"prevItem":{"title":"Le Campus Condorcet accueille la Journ\xe9e professionnelle 2026","permalink":"/en/blog/journees-2026"},"nextItem":{"title":"Construction et animation d\'une communaut\xe9 autour du d\xe9veloppement d\'un logiciel libre","permalink":"/en/blog/anf-autrans"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nOlesea Dubois (Sciences Po Paris) et Vincent Tardif (ENS paris) ont eu le plaisir de pr\xe9senter NumaHOP aux Journ\xe9es LIBER 2026 qui ont r\xe9uni une large communaut\xe9 europ\xe9enne de biblioth\xe8ques de recherche autour des enjeux strat\xe9giques li\xe9s aux infrastructures num\xe9riques et \xe0 la gestion des collections et \xe0 la science ouverte. L\'\xe9dition de cette ann\xe9e \xe0 particuli\xe8rement mis en avant les outils permettant de renforcer la r\xe9silience des biblioth\xe8ques face aux \xe9volutions technologiques rapides ainsi que les solutions collaboratives.\\n\\nL\'occasion de revenir sur les \xe9volutions de NumaHOP, sur la dynamique de la communaut\xe9 d\'utilisateurs et sur les perspectives ouvertes par l\'association pour les ann\xe9es \xe0 venir.\\n\\n<Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [Site officiel de LIBER 2026](https://liberconference.eu/).\\n\\n\x3c!-- truncate --\x3e\\n\\n![NumaHOP \xe0 LIBER 2026](/img/visuels/liber-trondheim.jpg)"},{"id":"anf-autrans","metadata":{"permalink":"/en/blog/anf-autrans","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-07-03-anf-autrans.md","source":"@site/blog/2026-07-03-anf-autrans.md","title":"Construction et animation d\'une communaut\xe9 autour du d\xe9veloppement d\'un logiciel libre","description":"Cette semaine, Pauline Rivi\xe8re (BSG) et Fran\xe7ois Gandolfi (Humath\xe8que Condorcet) ont repr\xe9sent\xe9 le projet NumaHOP lors de l\u2019Action National de Formation (ANF) organis\xe9 par l\u2019Universit\xe9 Grenoble Alpes (UGA). Cet \xe9v\xe9nement, d\xe9di\xe9 \xe0 la construction et \xe0 l\u2019animation de communaut\xe9s autour des logiciels libres, a permis d\u2019\xe9changer sur des enjeux juridiques, techniques et communautaires, trois dimensions essentielles pour la p\xe9rennit\xe9 des projets open source.","date":"2026-07-03T00:00:00.000Z","tags":[{"inline":false,"label":"S\xe9minaires & Conf\xe9rences","permalink":"/en/blog/tags/conf"}],"hasTruncateMarker":true,"authors":[{"name":"Pauline Rivi\xe8re","title":"Biblioth\xe8que Sainte Genevi\xe8ve","page":{"permalink":"/en/blog/authors/priviere"},"imageURL":"/en/img/photos/priviere.jpg","key":"priviere"},{"name":"Fran\xe7ois Gandolfi","title":"Humath\xe8que Condorcet","page":{"permalink":"/en/blog/authors/fgandolfi"},"imageURL":"/en/img/photos/fgandolfi.jpg","key":"fgandolfi"}],"frontMatter":{"slug":"anf-autrans","title":"Construction et animation d\'une communaut\xe9 autour du d\xe9veloppement d\'un logiciel libre","date":"2026-07-03T00:00:00.000Z","tags":["conf"],"authors":["priviere","fgandolfi"]},"unlisted":false,"prevItem":{"title":"Conf\xe9rence annuelle de la Ligue des Biblioth\xe8ques Europ\xe9ennes de Recherche","permalink":"/en/blog/liber-trondheim"},"nextItem":{"title":"Retour sur les JDEV 2026 \xe0 Montpellier : NumaHOP sous les projecteurs","permalink":"/en/blog/jdev-montpellier"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nCette semaine, Pauline Rivi\xe8re (BSG) et Fran\xe7ois Gandolfi (Humath\xe8que Condorcet) ont repr\xe9sent\xe9 le projet NumaHOP lors de l\u2019Action National de Formation (ANF) organis\xe9 par l\u2019**Universit\xe9 Grenoble Alpes** (UGA). Cet \xe9v\xe9nement, d\xe9di\xe9 \xe0 la construction et \xe0 l\u2019animation de communaut\xe9s autour des **logiciels libres**, a permis d\u2019\xe9changer sur des enjeux juridiques, techniques et communautaires, trois dimensions essentielles pour la p\xe9rennit\xe9 des projets *open source*.\\n\\n<Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [Site officiel de l\'ANF](https://animeopensource.sciencesconf.org/)\\n\\n\x3c!-- truncate --\x3e\\n\\n### Les interventions pl\xe9ni\xe8res : trois approches compl\xe9mentaires\\n\\nL\u2019ANF a \xe9t\xe9 rythm\xe9e par trois conf\xe9rences pl\xe9ni\xe8res offrant des perspectives vari\xe9es sur l\u2019open source :\\n\\n- <Icon icon={[\\"fa\\", \\"people-arrows\\"]} /> Approche sociologique :\\n  *Au-del\xe0 des mondes antagonistes : les \xe9conomies enchev\xeatr\xe9es du logiciel libre et de l\u2019industrie informatique*\\n  Intervenant : Gabriel Alcaras (Sciences Po Paris, M\xe9diaLab).\\n\\n- <Icon icon={[\\"fa\\", \\"gavel\\"]} /> Approche juridique :\\n  *La probl\xe9matique juridique*\\n  Intervenant : J\xe9r\xe9my Pappalardo, avocat sp\xe9cialis\xe9 en droit de la propri\xe9t\xe9 intellectuelle et de l\u2019innovation.\\n\\n- <Icon icon={[\\"fa\\", \\"wrench\\"]} /> Approche pratique et technique :\\n  *La question de la gouvernance*\\n  Intervenants : Myka\xebl Vigo (IGE, CNRS) et Antonin Delpeuch (T\xe9l\xe9com Paris).\\n\\n### NumaHOP au c\u0153ur des \xe9changes\\n\\nPauline et Fran\xe7ois sont intervenus dans chaque session de la deuxi\xe8me partie de l\u2019ANF, o\xf9 ils ont positionn\xe9 NumaHOP comme un cas d\u2019\xe9tude concret \xe0 travers les trois prismes abord\xe9s :\\n- <Icon icon={[\\"fa\\", \\"gavel\\"]} /> Juridique : licence, propri\xe9t\xe9 intellectuelle et cadre l\xe9gal.\\n- <Icon icon={[\\"fa\\", \\"wrench\\"]} /> Technique : gouvernance du code et organisation du d\xe9veloppement.\\n- <Icon icon={[\\"fa\\", \\"users\\"]} /> Communautaire : animation, collaboration et p\xe9rennisation du projet.\\n\\nBien que le monde de la documentation ait \xe9t\xe9 peu repr\xe9sent\xe9 (\xe0 l\u2019exception de coll\xe8gues biblioth\xe9caires et de l\u2019atelier de la donn\xe9e de l\u2019UGA), les retours sur les t\xe9moignages de NumaHOP ont \xe9t\xe9 tr\xe8s positifs. L\u2019**historique du projet**, d\xe9taill\xe9 par Pauline, a particuli\xe8rement marqu\xe9 les participants, offrant une vision claire de son \xe9volution et des d\xe9fis rencontr\xe9s.\\n\\n### NumaHOP : des atouts \xe0 valoriser\\n\\nCette participation a permis de mettre en lumi\xe8re plusieurs forces du projet.\\n\\n- <Icon icon={[\\"fa\\", \\"check\\"]} /> Une licence adapt\xe9e :\\nle choix de la **licence AGPL** pour NumaHOP s\u2019av\xe8re judicieux, car elle autorise une distribution locale ou en SaaS (*Software as a Service*), tout en prot\xe9geant le code source.\\n\\n- <Icon icon={[\\"fa\\", \\"check\\"]} /> Une identit\xe9 prot\xe9g\xe9e :\\nla marque et les **noms de domaine** ont \xe9t\xe9 acquis d\xe8s l\u2019origine, ce qui renforce la cr\xe9dibilit\xe9 et la visibilit\xe9 du projet.\\n\\n- <Icon icon={[\\"fa\\", \\"check\\"]} /> Une maturit\xe9 communautaire :\\nNumaHOP se distingue par son **mod\xe8le associatif** inter-\xe9tablissements, une approche encore peu r\xe9pandue dans l\u2019\xe9cosyst\xe8me des logiciels libres acad\xe9miques, o\xf9 les projets restent souvent cantonn\xe9s \xe0 un laboratoire ou un campus.\\n\\nCependant, il reste des d\xe9fis \xe0 relever, notamment sur le plan technique, o\xf9 NumaHOP accuse un certain retard par rapport \xe0 d\u2019autres projets.\\n\\n### Perspectives pour l\u2019association NumaHOP\\n\\n\xc0 l\u2019issue de cette ANF, deux priorit\xe9s \xe9mergent pour l\u2019association. D\'une part, l\u2019appropriation technique : il est essentiel que les membres du bureau et la communaut\xe9 s\u2019approprient le d\xe9p\xf4t GitHub et ses fonctionnalit\xe9s cl\xe9s (gestion des issues, contributions, etc.).Cela permettrait de faire vivre le projet en synergie avec les prestataires, tout en renfor\xe7ant l\u2019autonomie de la communaut\xe9. D\'autre part, la recherche de financements : pour r\xe9sorber la dette technique et relancer le projet sur des bases solides, la qu\xeate de financements reste une priorit\xe9.\\n\\n### Conclusion\\n\\nCette ANF a confirm\xe9 que NumaHOP dispose d\u2019atouts majeurs pour son avenir, mais aussi de pistes claires pour progresser. Les \xe9changes avec les autres participants ont \xe9t\xe9 riches en enseignements, et les retours positifs sur le projet renforcent sa l\xe9gitimit\xe9 dans l\u2019\xe9cosyst\xe8me du logiciel libre.\\n\\n\\n![NumaHOP \xe0 l\'ANF Construction et animation d\'une communaut\xe9 autour du d\xe9veloppement d\'un logiciel libre](/img/visuels/anf-autrans.jpg)"},{"id":"jdev-montpellier","metadata":{"permalink":"/en/blog/jdev-montpellier","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-06-25-jdev-montpellier.md","source":"@site/blog/2026-06-25-jdev-montpellier.md","title":"Retour sur les JDEV 2026 \xe0 Montpellier : NumaHOP sous les projecteurs","description":"Du 22 au 26 juin 2026, s\u2019est tenue \xe0 Montpellier la 12e \xe9dition des Journ\xe9es du D\xe9veloppement Logiciel (JDEV), un \xe9v\xe9nement incontournable pour les acteurs du logiciel dans l\u2019Enseignement Sup\xe9rieur et la Recherche (ESR). Olesea DUbois (Sciences Po Paris) et Fran\xe7ois Gandolfi (Humath\xe8que Condorcet) y ont repr\xe9sent\xe9 NumaHOP pour une intervention intitul\xe9e :","date":"2026-06-25T00:00:00.000Z","tags":[{"inline":false,"label":"S\xe9minaires & Conf\xe9rences","permalink":"/en/blog/tags/conf"}],"hasTruncateMarker":true,"authors":[{"name":"Olesea Dubois","title":"Sciences Po Paris","page":{"permalink":"/en/blog/authors/odubois"},"imageURL":"/en/img/photos/odubois.jpg","key":"odubois"},{"name":"Fran\xe7ois Gandolfi","title":"Humath\xe8que Condorcet","page":{"permalink":"/en/blog/authors/fgandolfi"},"imageURL":"/en/img/photos/fgandolfi.jpg","key":"fgandolfi"}],"frontMatter":{"slug":"jdev-montpellier","title":"Retour sur les JDEV 2026 \xe0 Montpellier : NumaHOP sous les projecteurs","date":"2026-06-25T00:00:00.000Z","tags":["conf"],"authors":["odubois","fgandolfi"]},"unlisted":false,"prevItem":{"title":"Construction et animation d\'une communaut\xe9 autour du d\xe9veloppement d\'un logiciel libre","permalink":"/en/blog/anf-autrans"},"nextItem":{"title":"NumaHOP au Digital Humanities Summer Institute 2026 \xe0 Montr\xe9al","permalink":"/en/blog/dhsi-montreal"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nDu 22 au 26 juin 2026, s\u2019est tenue \xe0 Montpellier la 12e \xe9dition des **Journ\xe9es du D\xe9veloppement Logiciel** (JDEV), un \xe9v\xe9nement incontournable pour les acteurs du logiciel dans l\u2019**Enseignement Sup\xe9rieur et la Recherche** (ESR). Olesea DUbois (Sciences Po Paris) et Fran\xe7ois Gandolfi (Humath\xe8que Condorcet) y ont repr\xe9sent\xe9 NumaHOP pour une intervention intitul\xe9e :\\n*De la num\xe9risation \xe0 la gestion des contenus num\xe9ris\xe9s : r\xe9pondre collectivement aux d\xe9fis des savoirs scientifiques*.\\n\\n<Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [Site officiel des JDEV 2026](https://jdev26.sciencesconf.org/?lang=fr).\\n\\n\x3c!-- truncate --\x3e\\n\\n### NumaHOP \xe0 l\u2019honneur\\n\\nNotre session, qui s\u2019est d\xe9roul\xe9e le mercredi 24 juin, avait pour objectif de pr\xe9senter les grandes lignes de la naissance et du fonctionnement de NumaHOP, et de recueillir les retours des participants sur les d\xe9veloppements futurs du logiciel.\\n\\nNous en avons profit\xe9 pour solliciter des conseils sur les priorit\xe9s \xe0 donner \xe0 ces d\xe9veloppements. Les retours ont \xe9t\xe9 unanimes : la premi\xe8re priorit\xe9 doit \xeatre celle de la **mise \xe0 jour du front-end** (passage de AngularJS \xe0 Angular), avant d\'envisager la **modernisation du back-end** (SpringBoot).\\n\\nNous avons \xe9galement appris l\u2019existence du [**Catalogue des logiciels libres de la recherche acad\xe9mique**](https://hal.science/). Une fois le d\xe9p\xf4t de NumaHOP effectu\xe9 sur HAL, le logiciel y sera r\xe9f\xe9renc\xe9, ce qui renforcera sa visibilit\xe9 dans l\u2019\xe9cosyst\xe8me de la recherche.\\n\\n### Un programme riche et vari\xe9\\n\\nLes s\xe9ances pl\xe9ni\xe8res des matin\xe9es ont abord\xe9 des th\xe8mes centraux pour le d\xe9veloppement logiciel dans l\u2019ESR :\\n- **ILAAS**, une f\xe9d\xe9ration mutualis\xe9e pour une IA g\xe9n\xe9rative souveraine.\\n- Les r\xe9seaux de l\u2019ESR li\xe9s au d\xe9veloppement logiciel.\\n- **LaSuite**, les outils num\xe9riques des agents publics.\\n\\nLes JDEV 2026 ont propos\xe9 un programme tr\xe8s dense, avec des interventions courtes (30 minutes \xe0 1 heure max) couvrant un large \xe9ventail de sujets. Voici quelques-unes des pr\xe9sentations marquantes auxquelles nous avons pu assist\xe9 :\\n- **Enrichissement des m\xe9tadonn\xe9es d\u2019un logiciel sur un d\xe9p\xf4t Git** (LAPP, CNRS).\\n- Le nouveau **Catalogue des logiciels pour la recherche** (Laboratoire Jean Kuntzmann, Grenoble).\\n- **TowSty** : Un programme Julia pour g\xe9n\xe9rer un site \xe0 partir de l\u2019\xe9diteur Stylo (Caen).\\n- **Flask** : Framework Python pour le d\xe9veloppement d\u2019applications (Institut des Sciences de l\u2019Ing\xe9nierie et des Syst\xe8mes, CNRS).\\n- **Le Proc\xe8s de l\u2019IA** : Une conf\xe9rence interactive dans le cadre du programme FIDLE du CNRS.\\n- **Contribuer \xe0 Debian : Comment le synchrotron SOLEIL rel\xe8ve le d\xe9fi de la gestion des d\xe9pendances scientifiques**.\\n- **Curation de m\xe9tadonn\xe9es** : Un outil respectant des standards internationaux en sciences sociales (INED).\\n- **Inf\xe9rence de LLM et syst\xe8mes d\u2019agents** (Institut du D\xe9veloppement et des Ressources en Informatique Scientifique, CNRS).\\n- **GreenScore Web et Ecofloc** : Mesurer et sensibiliser \xe0 l\u2019empreinte carbone et \xe0 la consommation \xe9nerg\xe9tique.\\n- **IA g\xe9n\xe9rative et institutions patrimoniales** : Retours d\u2019exp\xe9rience et adaptations.\\n- **Licences et gestion des projets logiciels libres** (Fran\xe7ois Pellegrini, CNRS).\\n- **Mise en place d\u2019une forge institutionnelle** : Retour d\u2019exp\xe9rience sur la conception, le d\xe9ploiement et la gouvernance \xe0 l\'INRAE.\\n\\nLa majorit\xe9 des participants et intervenants \xe9taient des d\xe9veloppeurs issus des sciences dures, mais quelques interventions concernaient les Sciences Humaines et Sociales (SHS).\\n\\n### Perspectives et opportunit\xe9s pour NumaHOP\\n\\n#### Une visibilit\xe9 renforc\xe9e\\nNotre intervention a suscit\xe9 un vif int\xe9r\xeat, notamment de la part de Pers\xe9e, qui \xe9tait pr\xe9sent lors de notre pr\xe9sentation. Les d\xe9veloppeurs grenoblois nous ont \xe9galement partag\xe9 qu\u2019ils utilisaient des scripts maison pour la num\xe9risation, mais qu\u2019aucun outil ne r\xe9pondait pleinement \xe0 leurs exigences pour les donn\xe9es en sciences dures.\\n\\n#### Des pistes \xe0 explorer\\nPlusieurs opportunit\xe9s ont \xe9merg\xe9 lors de ces journ\xe9es :\\n- Financements UNESCO : des financements pourraient \xeatre disponibles pour des activit\xe9s similaires \xe0 celles de NumaHOP. Une piste \xe0 creuser !\\n- Collaboration avec l\u2019Institut de l\'Information Scientifique et Technique (INIST), qui d\xe9ploie d\xe9j\xe0 des solutions Omeka pour les \xe9tablissements, une collaboration pourrait \xeatre envisag\xe9e.\\n- La \\"souverainet\xe9\\" : un mot cl\xe9 dans les appels \xe0 projets actuels, \xe0 int\xe9grer dans les prochaines candidatures en faveur de NumaHOP.\\n\\n### Conclusion\\n\\nLes JDEV 2026 ont \xe9t\xe9 une exp\xe9rience enrichissante pour NumaHOP, avec des retours positifs, des pistes de financement et des opportunit\xe9s de collaboration. Ces journ\xe9es ont aussi confirm\xe9 l\u2019importance de moderniser notre outil pour r\xe9pondre aux besoins croissants de la communaut\xe9.\\n\\n![NumaHOP aux DEV 2026](/img/visuels/jdev-montpellier.jpeg)"},{"id":"dhsi-montreal","metadata":{"permalink":"/en/blog/dhsi-montreal","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-06-18-dhsi-montreal.md","source":"@site/blog/2026-06-18-dhsi-montreal.md","title":"NumaHOP au Digital Humanities Summer Institute 2026 \xe0 Montr\xe9al","description":"Du 3 au 7 juin 2026, NumaHOP a \xe9t\xe9 pr\xe9sent\xe9 par Olesea Dubois (Sciences Po Paris) au Digital Humanities Summer Institute (DHSI) de l\u2019Universit\xe9 de Montr\xe9al. Cet \xe9v\xe9nement a r\xe9uni des chercheurs, biblioth\xe9caires, archivistes, ing\xe9nieurs et responsables de projets num\xe9riques autour des enjeux li\xe9s \xe0 la pr\xe9servation, valorisation et exploitation des patrimoines num\xe9riques.","date":"2026-06-18T00:00:00.000Z","tags":[{"inline":false,"label":"S\xe9minaires & Conf\xe9rences","permalink":"/en/blog/tags/conf"}],"hasTruncateMarker":true,"authors":[{"name":"Olesea Dubois","title":"Sciences Po Paris","page":{"permalink":"/en/blog/authors/odubois"},"imageURL":"/en/img/photos/odubois.jpg","key":"odubois"}],"frontMatter":{"slug":"dhsi-montreal","title":"NumaHOP au Digital Humanities Summer Institute 2026 \xe0 Montr\xe9al","date":"2026-06-18T00:00:00.000Z","tags":["conf"],"authors":["odubois"]},"unlisted":false,"prevItem":{"title":"Retour sur les JDEV 2026 \xe0 Montpellier : NumaHOP sous les projecteurs","permalink":"/en/blog/jdev-montpellier"},"nextItem":{"title":"Sortie de NumaHOP 26.03 : une version de transition vers l\'avenir","permalink":"/en/blog/release-2603"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\n\\nDu 3 au 7 juin 2026, NumaHOP a \xe9t\xe9 pr\xe9sent\xe9 par Olesea Dubois (Sciences Po Paris) au **Digital Humanities Summer Institute (DHSI)** de l\u2019**Universit\xe9 de Montr\xe9al**. Cet \xe9v\xe9nement a r\xe9uni des chercheurs, biblioth\xe9caires, archivistes, ing\xe9nieurs et responsables de projets num\xe9riques autour des enjeux li\xe9s \xe0 la **pr\xe9servation, valorisation et exploitation des patrimoines num\xe9riques**.\\n\\n<Icon icon={[\\"fa\\", \\"arrow-up-right-from-square\\"]} /> [Site officiel des DHSI 2026](https://dhsi.org/).\\n\\n\x3c!-- truncate --\x3e\\n\\n### Une pr\xe9sentation remarqu\xe9e\\n\\nLa pr\xe9sentation de NumaHOP a suscit\xe9 un vif int\xe9r\xeat, en particulier gr\xe2ce \xe0 son **mod\xe8le open source** et son **positionnement dans les infrastructures patrimoniales et de recherche**. Les \xe9changes avec le public ont principalement port\xe9 sur trois th\xe9matiques actuelles: la **cybers\xe9curit\xe9**, l\u2019**intelligence artificielle**, et la **p\xe9rennit\xe9 \xe9conomique**.\\n\\n#### Cybers\xe9curit\xe9 : une pr\xe9occupation majeure\\n\\nLes participants ont exprim\xe9 des craintes croissantes concernant la s\xe9curisation des infrastructures num\xe9riques patrimoniales, notamment dans des environnements interconnect\xe9s. Leurs questions ont port\xe9 sur la gestion des acc\xe8s et des habilitations, la protection des documents et des m\xe9tadonn\xe9es associ\xe9es, la s\xe9curisation des \xe9changes avec les syst\xe8mes tiers d\xe9di\xe9s \xe0 l\'archivage et \xe0 la diffusion, et enfin \xe0 l\u2019int\xe9gration des recommandations en mati\xe8re de cybers\xe9curit\xe9 dans les d\xe9veloppements. Ces interrogations refl\xe8tent une tendance forte dans le secteur, o\xf9 la s\xe9curit\xe9 des donn\xe9es devient un enjeu central pour les projets num\xe9riques.\\n\\n#### L\u2019intelligence artificielle : un sujet cl\xe9\\n\\nL\u2019**IA** a \xe9t\xe9 l\u2019un des th\xe8mes les plus discut\xe9s. Les participants ont souhait\xe9 savoir si NumaHOP int\xe8gre d\xe9j\xe0 des fonctionnalit\xe9s bas\xe9es sur l\u2019IA. La question se pose de savoir quelles pourraient \xeatre les perspectives d\u2019int\xe9gration de cette technologie et comment l\u2019IA pourrait am\xe9liorer les workflows de num\xe9risation, en particulier dans l\'enrichissement des m\xe9tadonn\xe9es et l\'assistance \xe0 la description des contenus. N\xe9anmoins, les \xe9changes ont \xe9galement soulign\xe9 la n\xe9cessit\xe9 d\u2019encadrer ces usages pour garantir \xe0 la fois la qualit\xe9 scientifique des documents produits et la transparence des traitements r\xe9alis\xe9s.\\n\\n#### P\xe9rennit\xe9 \xe9conomique : une question centrale\\n\\nLa viabilit\xe9 \xe0 long terme de NumaHOP a \xe9t\xe9 l\u2019une des questions les plus r\xe9currentes. Les participants ont souhait\xe9 comprendre comment le projet \xe9tait financ\xe9, et connaitre les acteurs qui contribuent \xe0 son d\xe9veloppement.\\n\\nAssurer la maintenance et l\'\xe9volution dans la dur\xe9e des projets *open source* du secteur patrimonial est un sujet r\xe9curent. Les discussions ont permis de rappeler que la p\xe9rennit\xe9 de NumaHOP reposait sur l\u2019engagement durable des \xe9tablissements utilisateurs qui permet une mutualisation des d\xe9veloppements. Par ailleurs, les financements obtenus via des appels \xe0 projets sont soutenu par l\'animation de la communaut\xe9 d\u2019utilisateurs. Un soutien institutionnel serait un atout majeur pour assurer la stabilit\xe9 du projet.\\n\\n### Des retours positifs et des opportunit\xe9s\\n\\nCette pr\xe9sentation a permis de renforcer la visibilit\xe9 de NumaHOP aupr\xe8s d\u2019un public international. Plusieurs participants ont manifest\xe9 leur int\xe9r\xeat pour contribuer au projet, notamment une doctorante \xe0 l\u2019Universit\xe9 de Montr\xe9al et \xe0 l\u2019Universit\xe9 Bretagne Sud, sp\xe9cialis\xe9e dans la cybers\xe9curit\xe9 des num\xe9risations patrimoniales, et un postdoctorant \xe0 l\u2019Universit\xe9 de Waterloo, travaillant sur la p\xe9dagogie de l\u2019IA et l\u2019histoire num\xe9rique du livre.\\n\\n### Conclusion\\n\\nLes discussions au DHSI 2026 ont confirm\xe9 que les pr\xe9occupations de la communaut\xe9 internationale des humanit\xe9s num\xe9riques convergent autour de la s\xe9curisation des infrastructures num\xe9riques face aux risques cyber et l\u2019int\xe9gration raisonn\xe9e de l\u2019intelligence artificielle** dans les processus documentaires et patrimoniaux. Ces \xe9changes ont \xe9galement mis en lumi\xe8re des pistes de r\xe9flexion pour les futurs travaux de la communaut\xe9 NumaHOP et assurer la p\xe9rennit\xe9 \xe9conomique des projets *open source*."},{"id":"release-2603","metadata":{"permalink":"/en/blog/release-2603","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2026-04-23-release-2603.md","source":"@site/blog/2026-04-23-release-2603.md","title":"Sortie de NumaHOP 26.03 : une version de transition vers l\'avenir","description":"BibLibre a le plaisir d\u2019annoncer la disponibilit\xe9 de la version NumaHOP 26.03, dont Adrien Derobert-Mazure a assur\xe9 le r\xf4le de release manager. Cette version marque une \xe9tape cl\xe9 dans l\u2019\xe9volution du logiciel, m\xeame si elle n\u2019introduit pas de changements majeurs visibles c\xf4t\xe9 interface utilisateur. Elle pose en revanche des bases essentielles pour les d\xe9veloppements \xe0 venir.","date":"2026-04-23T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/en/blog/tags/release"},{"inline":false,"label":"Biblibre","permalink":"/en/blog/tags/biblibre"}],"hasTruncateMarker":true,"authors":[{"name":"S\xe9verine Queune","title":"BibLibre","page":{"permalink":"/en/blog/authors/squeune"},"imageURL":"/en/img/photos/biblibre.jpg","key":"squeune"},{"name":"Adrien Derobert-Mazure","title":"Biblibre","page":{"permalink":"/en/blog/authors/aderobert"},"imageURL":"/en/img/photos/biblibre.jpg","key":"aderobert"}],"frontMatter":{"slug":"release-2603","title":"Sortie de NumaHOP 26.03 : une version de transition vers l\'avenir","date":"2026-04-23T00:00:00.000Z","tags":["release","biblibre"],"authors":["squeune","aderobert"]},"unlisted":false,"prevItem":{"title":"NumaHOP au Digital Humanities Summer Institute 2026 \xe0 Montr\xe9al","permalink":"/en/blog/dhsi-montreal"},"nextItem":{"title":"Journ\xe9es NumaHOP & Omeka 2024 : retour sur un \xe9v\xe9nement cl\xe9 pour la num\xe9risation et la valorisation du patrimoine","permalink":"/en/blog/journees-2024"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nBibLibre a le plaisir d\u2019annoncer la disponibilit\xe9 de la version NumaHOP 26.03, dont Adrien Derobert-Mazure a assur\xe9 le r\xf4le de *release manager*. Cette version marque une \xe9tape cl\xe9 dans l\u2019\xe9volution du logiciel, m\xeame si elle n\u2019introduit pas de changements majeurs visibles c\xf4t\xe9 interface utilisateur. Elle pose en revanche des bases essentielles pour les d\xe9veloppements \xe0 venir.\\n\\n<Icon icon={[\\"fa\\", \\"download\\"]} /> [T\xe9l\xe9charger le d\xe9tail de la release 26.03](/img/visuels/release-2603.pdf)\\n\\n\x3c!-- truncate --\x3e\\n\\n### Un versionnage calendaire pour plus de lisibilit\xe9\\n\\nD\xe9sormais, NumaHOP adopte un versionnage calendaire, avec deux versions publi\xe9es chaque ann\xe9e :\\n- Une version en mars\\n- Une version en septembre\\n\\nCe changement vise \xe0 rendre le projet plus lisible et pr\xe9visible pour l\u2019ensemble de la communaut\xe9.\\n\\n<Icon icon={[\\"fa\\", \\"code-pull-request\\"]} /> [La version 26.03 sur GitHub](https://animeopensource.sciencesconf.org/)\\n\\n### Une documentation centralis\xe9e et collaborative\\n\\nLa documentation technique de NumaHOP \xe9volue et sera d\xe9sormais :\\n- Centralis\xe9e et g\xe9r\xe9e sur GitHub pour faciliter les contributions\\n- Disponible en anglais dans une logique d\u2019internationalisation\\n- Traduite progressivement pour r\xe9pondre aux besoins de tous les publics (d\xe9veloppeurs, utilisateurs, administrateurs)\\n\\nCette nouvelle organisation s\u2019inscrit dans une dynamique collaborative et vise \xe0 enrichir progressivement la documentation pour couvrir les attentes de tous.\\n\\n<Icon icon={[\\"fa\\", \\"code-pull-request\\"]} /> [Acc\xe9der \xe0 la documentation d\xe9veloppeur en ligne](https://numahop.github.io/Documentation/)\\n\\n### Am\xe9liorations techniques et consolidation\\n\\nCette version inclut :\\n- Des am\xe9liorations de la cha\xeene de d\xe9veloppement et de l\u2019infrastructure\\n- Des simplifications des processus pour renforcer la maintenabilit\xe9\\n- Des corrections de bugs et ajustements fonctionnels\\n\\nIl s\u2019agit donc d\u2019une version de transition, centr\xe9e sur la consolidation des fondations du projet et la pr\xe9paration des prochaines \xe9volutions."},{"id":"journees-2024","metadata":{"permalink":"/en/blog/journees-2024","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2024-11-22-journees-2024.md","source":"@site/blog/2024-11-22-journees-2024.md","title":"Journ\xe9es NumaHOP & Omeka 2024 : retour sur un \xe9v\xe9nement cl\xe9 pour la num\xe9risation et la valorisation du patrimoine","description":"Les journ\xe9es NumaHOP 2024 ont \xe9t\xe9 organis\xe9es conjointement avec l\u2019association des usagers franophones d\u2019Omeka, et ont eu lieu du 20 au 22 novembre \xe0 l\u2019ENS de Lyon. Elles ont \xe9t\xe9 l\u2019occasion de faire un point sur les avanc\xe9es, d\xe9fis et perspectives de ces deux outils compl\xe9mentaires pour la gestion des cha\xeenes de num\xe9risation et la valorisation des collections patrimoniales. Voici les temps forts li\xe9s \xe0 NumaHOP.","date":"2024-11-22T00:00:00.000Z","tags":[{"inline":false,"label":"Journ\xe9es professionnelles","permalink":"/en/blog/tags/journeespro"},{"inline":false,"label":"ENS de Lyon","permalink":"/en/blog/tags/enslyon"}],"hasTruncateMarker":true,"authors":[{"name":"Pauline Rivi\xe8re","title":"Biblioth\xe8que Sainte Genevi\xe8ve","page":{"permalink":"/en/blog/authors/priviere"},"imageURL":"/en/img/photos/priviere.jpg","key":"priviere"},{"name":"Olesea Dubois","title":"Sciences Po Paris","page":{"permalink":"/en/blog/authors/odubois"},"imageURL":"/en/img/photos/odubois.jpg","key":"odubois"}],"frontMatter":{"slug":"journees-2024","title":"Journ\xe9es NumaHOP & Omeka 2024 : retour sur un \xe9v\xe9nement cl\xe9 pour la num\xe9risation et la valorisation du patrimoine","date":"2024-11-22T00:00:00.000Z","tags":["journeespro","enslyon"],"authors":["priviere","odubois"]},"unlisted":false,"prevItem":{"title":"Sortie de NumaHOP 26.03 : une version de transition vers l\'avenir","permalink":"/en/blog/release-2603"},"nextItem":{"title":"Ouvroir 2 NumaHOP","permalink":"/en/blog/ouvroir2"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nLes journ\xe9es NumaHOP 2024 ont \xe9t\xe9 organis\xe9es conjointement avec l\u2019association des usagers franophones d\u2019Omeka, et ont eu lieu du 20 au 22 novembre \xe0 l\u2019ENS de Lyon. Elles ont \xe9t\xe9 l\u2019occasion de faire un point sur les avanc\xe9es, d\xe9fis et perspectives de ces deux outils compl\xe9mentaires pour la gestion des cha\xeenes de num\xe9risation et la valorisation des collections patrimoniales. Voici les temps forts li\xe9s \xe0 NumaHOP.\\n\\n\x3c!-- truncate --\x3e\\n\\n#### Migration historique : l\'instance mutualis\xe9e NumaHOP chez BibLibre\\nUn moment cl\xe9 de ces journ\xe9es a \xe9t\xe9 le retour d\u2019exp\xe9rience sur la migration de l\u2019instance mutualis\xe9e NumaHOP (Biblioth\xe8que Sainte-Genevi\xe8ve, Sciences Po, BULAC) vers le prestataire BibLibre, effective depuis septembre 2024.\\n- Enjeux : Apr\xe8s la fin du contrat avec le d\xe9veloppeur historique, les trois \xe9tablissements ont d\xfb trouver un nouveau prestataire pour assurer l\u2019h\xe9bergement et la maintenance.\\n- D\xe9fis : Gestion des enjeux techniques et organisationnels, adaptation \xe0 un nouvel \xe9cosyst\xe8me de d\xe9veloppement multi-acteurs.\\n- Perspectives : Ouverture d\u2019un dialogue avec la communaut\xe9 pour faire \xe9voluer le logiciel dans ce nouveau cadre.\\n\\nIntervenants : Olesea Dubois (Sciences Po), Laurent Poligny (BSG), Gabriel Raupp (BULAC).\\n\\n#### NumaHOP et les archives : interop\xe9rabilit\xe9 et nouveaut\xe9s\\nPlusieurs sessions ont mis en lumi\xe8re l\u2019int\xe9gration de NumaHOP dans des workflows d\u2019archivage et son interop\xe9rabilit\xe9 avec d\u2019autres outils :\\n- Pr\xe9sentation du programme Archives de CollEx-Pers\xe9e (Judith Soria, Mus\xe9um national d\u2019histoire naturelle).\\n- D\xe9couverte de Vitam et de sa d\xe9marche d\u2019audit (Philippe Prat, CINES).\\n- Nouveaut\xe9s dans Calames (\xc9tienne Naddeo, ABES) : Adaptations r\xe9alis\xe9es gr\xe2ce aux retours de la communaut\xe9 NumaHOP.\\n\\nObjectif : Renforcer les liens entre NumaHOP et les \xe9cosyst\xe8mes d\u2019archivage pour une gestion fluide des donn\xe9es.\\n\\n#### Compl\xe9mentarit\xe9 avec Omeka : des flux optimis\xe9s\\nUne table ronde a illustr\xe9 la synergie entre NumaHOP et Omeka \xe0 travers trois exemples concrets :\\n1. Biblioth\xe8que de Sciences Po : Projet *\\"Le fonds Jean Longuet : don, num\xe9risation, diffusion\\"*.\\n2. Biblioth\xe8que de l\u2019ENS : Cr\xe9ation de la Biblioth\xe8que num\xe9rique de l\u2019ENS.\\n3. BULAC : Projet EpiPOM (*\xc9pigraphie du Proche-Orient m\xe9di\xe9val*), men\xe9 par Martina Massullo (chercheuse en r\xe9sidence en 2021-2022).\\n   - Cas d\u2019usage : Assemblage et comparaison d\u2019images via le protocole IIIF, avec des transcriptions HTR (Handwritten Text Recognition) int\xe9gr\xe9es dans Omeka S.\\n\\nAnimation : Hortense Longequeue (Biblioth\xe8que municipale de Lyon).\\n\\n#### Autres temps forts\\n- Pr\xe9sentation de l\u2019Ouvroir NumaHOP (Sarah Gauth\xe9, CollEx-Pers\xe9e) : Un projet ambitieux pour f\xe9d\xe9rer les pratiques autour de NumaHOP.\\n- Assembl\xe9e G\xe9n\xe9rale de l\u2019association NumaHOP : Moment d\u2019\xe9change pour d\xe9fini les priorit\xe9s de d\xe9veloppement et de diffusion du logiciel.\\n- Posters et d\xe9monstrations :\\n  - *Allineamento* : Alignement entre Omeka et IdRef (Laurent Aucher, Pauline Rivi\xe8re, Agnieszka Halczuk).\\n  - *Numaclay* : Valorisation des patrimoines scientifiques avec Omeka S (Oriane Boissel, Sylvie Sall\xe9).\\n\\n### Pourquoi ces journ\xe9es sont-elles importantes ?\\n- Partage d\u2019exp\xe9riences : Retour sur des migrations complexes, des bonnes pratiques et des solutions innovantes.\\n- Collaboration renforc\xe9e : \xc9changes entre d\xe9veloppeurs, biblioth\xe9caires, chercheurs et prestataires pour faire \xe9voluer les outils.\\n- Ouverture \xe0 la communaut\xe9 : Les journ\xe9es \xe9taient libres d\u2019acc\xe8s, favorisant l\u2019inclusion de tous les acteurs (petites \xe9quipes, chercheurs individuels, etc.).\\n\\n<Icon icon={[\\"fa\\", \\"external-link\\"]} /> [Association AUFO](https://aufo.fr)\\n\\n<Icon icon={[\\"fa\\", \\"external-link\\"]} /> [CollEx-Pers\xe9e](https://www.collex-pers\xe9e.fr)\\n\\n![Affiche Journ\xe9es 2024](/img/visuels/journees-2024.png)"},{"id":"ouvroir2","metadata":{"permalink":"/en/blog/ouvroir2","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2023-04-01-ouvroir2.md","source":"@site/blog/2023-04-01-ouvroir2.md","title":"Ouvroir 2 NumaHOP","description":"L\u2019Ouvroir 2 NumaHOP est un projet financ\xe9 par le GIS Collex-Pers\xe9e. Depuis mai 2022, une cheffe de projet a \xe9t\xe9 recrut\xe9e au sein des \xe9quipes de l\u2019UAR Pers\xe9e pour travailler sur ce projet.","date":"2023-04-01T00:00:00.000Z","tags":[{"inline":false,"label":"CollEx-Pers\xe9e","permalink":"/en/blog/tags/collex"}],"hasTruncateMarker":true,"authors":[{"name":"Sarah Gauth\xe9","title":"UAR Pers\xe9e","page":{"permalink":"/en/blog/authors/sgauthe"},"imageURL":"/en/img/logos/persee-logo.png","key":"sgauthe"}],"frontMatter":{"slug":"ouvroir2","title":"Ouvroir 2 NumaHOP","date":"2023-04-01T00:00:00.000Z","tags":["collex"],"authors":"sgauthe"},"unlisted":false,"prevItem":{"title":"Journ\xe9es NumaHOP & Omeka 2024 : retour sur un \xe9v\xe9nement cl\xe9 pour la num\xe9risation et la valorisation du patrimoine","permalink":"/en/blog/journees-2024"},"nextItem":{"title":"Journ\xe9es professionnelles 2022","permalink":"/en/blog/journees-2022"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nL\u2019Ouvroir 2 NumaHOP est un projet financ\xe9 par le GIS Collex-Pers\xe9e. Depuis mai 2022, une cheffe de projet a \xe9t\xe9 recrut\xe9e au sein des \xe9quipes de l\u2019UAR Pers\xe9e pour travailler sur ce projet.\\n\\n<Icon icon={[\\"fa\\", \\"display\\"]} /> [L\'Ouvroir NumaHOP 2 : Automatiser, fluidifier, collaborer et HOP !](https://www-test-collex.inist.fr/projet/louvroir-numahop-2/)\\n\\n\x3c!-- truncate --\x3e\\n\\nL\u2019Ouvroir 2 NumaHOP a pour objectif de d\xe9velopper l\u2019utilisation de NumaHOP au sein de la communaut\xe9 en s\u2019appuyant sur les retours des \xe9tablissements utilisateurs. Pour amplifier l\u2019utilisation de NumaHOP, l\u2019Ouvroir vise \xe0 proposer une documentation d\u2019aide \xe0 l\u2019installation et \xe0 la prise en main et \xe0 travailler sur une solution d\u2019h\xe9bergement de la plateforme. Pour ce faire, deux axes de travail ont \xe9t\xe9 d\xe9termin\xe9s :\\n\\n- Faciliter la mise en \u0153uvre de NumaHOP gr\xe2ce \xe0 un site web r\xe9unissant l\u2019ensemble des ressources techniques et documentaires n\xe9cessaires \xe0 l\u2019installation et la prise en main du progiciel par les \xe9quipes locales.\\n- Etudier les conditions de l\u2019ouverture d\u2019une instance mutualis\xe9e de NumaHOP tenant compte des conditions techniques, mat\xe9rielles, humaines et \xe9conomiques pour sa r\xe9alisation, ainsi que des sc\xe9narios de gouvernance pour la future plateforme."},{"id":"journees-2022","metadata":{"permalink":"/en/blog/journees-2022","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2022-11-24-journees-2022.md","source":"@site/blog/2022-11-24-journees-2022.md","title":"Journ\xe9es professionnelles 2022","description":"La journ\xe9e profesionnelle NumaHOP 2022 s\u2019est tenue \xe0 l\u2019Universit\xe9 Paris Saclay  le 24 novembre. Au programme : pr\xe9sentations, \xe9changes, et ateliers pour comprendre le fonctionnement de la communaut\xe9 utilisateurs.","date":"2022-11-24T00:00:00.000Z","tags":[{"inline":false,"label":"Journ\xe9es professionnelles","permalink":"/en/blog/tags/journeespro"},{"inline":false,"label":"Universit\xe9 Paris Saclay","permalink":"/en/blog/tags/saclay"}],"hasTruncateMarker":true,"authors":[{"name":"Oriane Boissel","title":"Universit\xe9 Paris Saclay","page":{"permalink":"/en/blog/authors/oboissel"},"imageURL":"/en/img/photos/oboissel.jpg","key":"oboissel"}],"frontMatter":{"slug":"journees-2022","title":"Journ\xe9es professionnelles 2022","date":"2022-11-24T00:00:00.000Z","tags":["journeespro","saclay"],"authors":"oboissel"},"unlisted":false,"prevItem":{"title":"Ouvroir 2 NumaHOP","permalink":"/en/blog/ouvroir2"},"nextItem":{"title":"Un premier article pour NumaHOP, la plateforme open source qui r\xe9volutionne la num\xe9risation des collections patrimoniales","permalink":"/en/blog/article-2020"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nLa journ\xe9e profesionnelle NumaHOP 2022 s\u2019est tenue \xe0 l\u2019Universit\xe9 Paris Saclay  le 24 novembre. Au programme : pr\xe9sentations, \xe9changes, et ateliers pour comprendre le fonctionnement de la communaut\xe9 utilisateurs.\\n\\n<Icon icon={[\\"fa\\", \\"circle-play\\"]} /> Retrouvez toutes les interventions en vid\xe9o !\\n\\n<Icon icon={[\\"fa\\", \\"signs-post\\"]} /> Le programme de la journ\xe9e\\n\\n\x3c!-- truncate --\x3e\\n\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [\\"NumaHOP en 2022\\"](https://www.youtube.com/watch?v=2MfVb5qzHew&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2), allocution d\u2019Herv\xe9 Dole, vice pr\xe9sident charg\xe9 de la culture \xe0 l\u2019Universit\xe9 Paris Saclay.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Retour d\u2019exp\xe9riences : les nouveaux utilisateurs de NumaHOP](https://www.youtube.com/watch?v=m5lVzfwx9CI&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=2), par Christophe Coignard (ENS de Paris), Laurence Gandois, Oriane Boissel (Universit\xe9 Paris Saclay) et Solenne Coutagne (Mus\xe9um national d\u2019Histoire Naturelle). Echange anim\xe9 par Sarah Gauth\xe9 (Pers\xe9e).\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [NumaHOP et ses usages : tour d\u2019horizon et d\xe9tournements](https://www.youtube.com/watch?v=64OCk8ckFwU&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=3), par Fran\xe7ois-Xavier Boffy (Universit\xe9 Lyon 1), Sylvie Sall\xe9 et Oriane Boissel (Universit\xe9 Paris Saclay), Pierre-Marie Bartoli (INHA). Echange anim\xe9 par Palmira de Sousa (Campus Condorcet).\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> Pr\xe9sentations flash: \\n  - [Le connecteur Limb Gallery](https://www.youtube.com/watch?v=0tLllZGQx3s&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=4), par Adeline Batailler (Sorbonne Universit\xe9).\\n  - [Le connecteur Omeka](https://www.youtube.com/watch?v=N__NvJb5OT0&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=6), par Pauline Rivi\xe8re (Biblioth\xe8que Sainte Genevi\xe8ve) et Olesea Dubois (Biblioth\xe8que de Sciences Po Paris)\\n  - [PDF oc\xe9ris\xe9s versus non oc\xe9ris\xe9s](https://www.youtube.com/watch?v=IDaoqkvYk4o&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=5), par Adeline Batailler (Sorbonne Universit\xe9).\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Pr\xe9sentation g\xe9n\xe9rale de NumaHOP](https://www.youtube.com/watch?v=JRLUKbGO7RE&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=7), par Laurence Gandois (Universit\xe9 Paris Saclay) et Pauline Rivi\xe8re (Biblioth\xe8que Sainte Genevi\xe8ve).\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [NumaHOP et les archives](https://www.youtube.com/watch?v=1K0FoVjaHh0&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=8), par Victor Beillard (Sorbonne Universit\xe9), Olesea Dubois (Biblioth\xe8que Sciences Po Paris), Nathalie Pilet (BULAC).\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Projet Collex Ouvroir 2 NumaHOP : un point d\u2019\xe9tape](https://www.youtube.com/watch?v=bbteyljxWSA&list=PLJFDLbH_mXeccEFt6RUI8PdUzV4NXGuP2&index=9), par Sarah Gauth\xe9 (Pers\xe9e).\\n\\n![Affiche Journ\xe9es 2024](/img/visuels/journees-2022.png)"},{"id":"article-2020","metadata":{"permalink":"/en/blog/article-2020","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2020-10-11-article-2020.md","source":"@site/blog/2020-10-11-article-2020.md","title":"Un premier article pour NumaHOP, la plateforme open source qui r\xe9volutionne la num\xe9risation des collections patrimoniales","description":"La num\xe9risation des collections patrimoniales est un d\xe9fi majeur pour les biblioth\xe8ques, archives et mus\xe9es. Chaque \xe9tablissement d\xe9veloppe souvent ses propres outils, ce qui conduit \xe0 une h\xe9t\xe9rog\xe9n\xe9it\xe9 des processus, une complexit\xe9 accrue et un manque de mutualisation. Pour y rem\xe9dier, trois \xe9tablissements pilotes \u2014 la biblioth\xe8que Sainte-Genevi\xe8ve, la biblioth\xe8que de Sciences Po-Paris et la Bulac \u2014 ont uni leurs forces pour cr\xe9er NumaHOP, une plateforme open source et collaborative.","date":"2020-10-11T00:00:00.000Z","tags":[{"inline":false,"label":"Publication","permalink":"/en/blog/tags/article"},{"inline":false,"label":"Biblioth\xe8que Sainte Genevi\xe8ve","permalink":"/en/blog/tags/bsg"},{"inline":false,"label":"Sciences Po Paris","permalink":"/en/blog/tags/sciencespo"},{"inline":false,"label":"Biblioth\xe8que universitaire des langues et civilisations","permalink":"/en/blog/tags/bulac"}],"hasTruncateMarker":true,"authors":[{"name":"Olesea Dubois","title":"Sciences Po Paris","page":{"permalink":"/en/blog/authors/odubois"},"imageURL":"/en/img/photos/odubois.jpg","key":"odubois"},{"name":"Pauline Rivi\xe8re","title":"Biblioth\xe8que Sainte Genevi\xe8ve","page":{"permalink":"/en/blog/authors/priviere"},"imageURL":"/en/img/photos/priviere.jpg","key":"priviere"},{"name":"Fanny Mion Mouton","title":"Biblioth\xe8que universitaire des langues et civilisations","page":{"permalink":"/en/blog/authors/fmionmouton"},"imageURL":"/en/img/photos/fmionmouton.jpg","key":"fmionmouton"}],"frontMatter":{"slug":"article-2020","title":"Un premier article pour NumaHOP, la plateforme open source qui r\xe9volutionne la num\xe9risation des collections patrimoniales","date":"2020-10-11T00:00:00.000Z","tags":["article","bsg","sciencespo","bulac"],"authors":["odubois","priviere","fmionmouton"]},"unlisted":false,"prevItem":{"title":"Journ\xe9es professionnelles 2022","permalink":"/en/blog/journees-2022"},"nextItem":{"title":"Une premi\xe8re journ\xe9e professionnelle pour NumaHOP","permalink":"/en/blog/journees-2019"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nLa num\xe9risation des collections patrimoniales est un d\xe9fi majeur pour les biblioth\xe8ques, archives et mus\xe9es. Chaque \xe9tablissement d\xe9veloppe souvent ses propres outils, ce qui conduit \xe0 une h\xe9t\xe9rog\xe9n\xe9it\xe9 des processus, une complexit\xe9 accrue et un manque de mutualisation. Pour y rem\xe9dier, trois \xe9tablissements pilotes \u2014 la biblioth\xe8que Sainte-Genevi\xe8ve, la biblioth\xe8que de Sciences Po-Paris et la Bulac \u2014 ont uni leurs forces pour cr\xe9er NumaHOP, une plateforme open source et collaborative.\\n\\nOlesea Dubois, Fanny Mion-Mouton et Pauline Rivi\xe8re nous livrent leur premier retour d\'experience un an apr\xe8s la mise en place de NumaHOP dan sleurs \xe9tablissements.\\n\\n<Icon icon={[\\"fa\\", \\"external-link\\"]} />  [Article disponible sur Arabesques](https://dx.doi.org/10.35562/arabesques.2239) !\\n\\n\x3c!-- truncate --\x3e\\n\\n### Une solution int\xe9gr\xe9e pour toute la cha\xeene de num\xe9risation\\nNumaHOP propose une cha\xeene de traitement simplifi\xe9e et automatis\xe9e, couvrant toutes les \xe9tapes d\u2019un projet de num\xe9risation. Automatiser, fluidifier et collaborer pour gagner en efficacit\xe9 et en coh\xe9rence.\\n\\n- Import des notices : Conversion automatique des formats Unimarc ou EAD vers Dublin Core.\\n- Gestion des documents : Organisation en projets, lots et trains, avec des outils de suivi comme des tableaux de bord et des statistiques.\\n- Contr\xf4le qualit\xe9 : Visionneuse performante pour v\xe9rifier les images et m\xe9tadonn\xe9es, avec des rapports normalis\xe9s pour les prestataires.\\n- Export automatis\xe9 : Vers des plateformes de stockage (Cines) ou de diffusion (*Internet Archive*, *Omeka*).\\n\\n### Bilan apr\xe8s un an d\u2019utilisation\\nLes \xe9tablissements pilotes ont observ\xe9 des gains significatifs, notamment en terme de r\xe9duction des co\xfbts de 30 \xe0 60 % sur les prestations de num\xe9risation. Les appels d\u2019offres s\'en trouvent simplifi\xe9s : les prestataires se concentrent sur la prise de vue, tandis que la gestion des m\xe9tadonn\xe9es est reprise en interne. L\'interface ergonomique permet \xe0 tous les agents, m\xeame non techniques, de s\u2019approprier l\u2019outil. En fin de compte, c\'est l\'harmonisation des pratiques et la standardisation des m\xe9thodes de travail que propose NumaHOP, tout en respectant param\xe9trages sp\xe9cifiques \xe0 chaque \xe9tablissement.\\n\\n### Et demain ?\\nNumaHOP est open source (disponible sur [GitHub](https://github.com/progilone/numahop)) et con\xe7u pour \xeatre partag\xe9 et am\xe9lior\xe9 par une communaut\xe9 d\u2019utilisateurs. Son adoption massive pourrait f\xe9d\xe9rer les savoir-faire et harmoniser les pratiques au sein du monde universitaire et culturel."},{"id":"journees-2019","metadata":{"permalink":"/en/blog/journees-2019","editUrl":"https://github.com/NumaHOP/UserDocumentation/edit/main/blog/2019-10-08-journees-2019.md","source":"@site/blog/2019-10-08-journees-2019.md","title":"Une premi\xe8re journ\xe9e professionnelle pour NumaHOP","description":"La premi\xe8re journ\xe9e profesionnelle NumaHOP s\u2019est tenue \xe0 la BULAC (Paris) dans l\u2019auditorium du P\xf4le Langues et Civilisation le 18 octobre 2019. Y \xe9taient programm\xe9es des pr\xe9sentations, des \xe9changes, des ateliers pour pr\xe9senter le progiciel.","date":"2019-10-08T00:00:00.000Z","tags":[{"inline":false,"label":"Journ\xe9es professionnelles","permalink":"/en/blog/tags/journeespro"},{"inline":false,"label":"Biblioth\xe8que universitaire des langues et civilisations","permalink":"/en/blog/tags/bulac"}],"hasTruncateMarker":true,"authors":[{"name":"Nathalie Pilet","title":"Biblioth\xe8que universitaire des langues et civilisations","page":{"permalink":"/en/blog/authors/npilet"},"imageURL":"/en/img/photos/npilet.jpg","key":"npilet"}],"frontMatter":{"slug":"journees-2019","title":"Une premi\xe8re journ\xe9e professionnelle pour NumaHOP","date":"2019-10-08T00:00:00.000Z","tags":["journeespro","bulac"],"authors":"npilet"},"unlisted":false,"prevItem":{"title":"Un premier article pour NumaHOP, la plateforme open source qui r\xe9volutionne la num\xe9risation des collections patrimoniales","permalink":"/en/blog/article-2020"}},"content":"import Icon from \'@site/src/components/Icon\';\\n\\nLa premi\xe8re journ\xe9e profesionnelle NumaHOP s\u2019est tenue \xe0 la BULAC (Paris) dans l\u2019auditorium du P\xf4le Langues et Civilisation le 18 octobre 2019. Y \xe9taient programm\xe9es des pr\xe9sentations, des \xe9changes, des ateliers pour pr\xe9senter le progiciel.\\n\\n<Icon icon={[\\"fa\\", \\"circle-play\\"]} />  Retrouvez toutes les interventions en vid\xe9o !\\n\\n\x3c!-- truncate --\x3e\\n\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Pourquoi une journ\xe9e NumaHOP ?](https://www.youtube.com/watch?v=9iVJMFaQ7MA&t=9s) Allocution de Fran\xe7ois Cavalier, directeur de la biblioth\xe8ques de Sciences Po Paris et Marie-Lise Tsagouria, directeur de la BULAC.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Qu\u2019est-ce qu\u2019un logiciel libre ?](https://www.youtube.com/watch?v=V-5Ux7l9rJk&t=1s) avec C\xe9cile Gobbo, responsable du p\xf4le Flux et Donn\xe9es \xe0 la BULAC et Nocpmas Legrand, administrateur technique du syst\xe8me d\u2019information documentaire \xe0 la BULAC.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Retour d\u2019exp\xe9riences](https://www.youtube.com/watch?v=DbvXiuVewg0&t=3s), par C\xe9cilia Piccioli, charg\xe9e des traitements de conservation \xe0 la BULAC, Pauline Bougon, charg\xe9e de num\xe9risation \xe0 la direction des ressources et de l\u2019information scientifique \xe0 Sciences Po Paris, Pauline Rivi\xe8re, chef de projet num\xe9risation \xe0 la biblioth\xe8que Sainte-Genevi\xe8ve. S\xe9ance anim\xe9e par Fanny Mion-Mouton, responsable adjointe du p\xf4le Flux et Donn\xe9es \xe0 la BULAC et responsable de l\u2019\xe9quipe signalement et exposition des donn\xe9es \xe0 la BULAC.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Regards des op\xe9rateurs nationaux](https://www.youtube.com/watch?v=t_IByhWNyS4), par Thomas Ledoux, charg\xe9 de la coordination projets DSI \xe0 la Biblioth\xe8que nationale de France, Alexia de Casanove, d\xe9partement Archivage et Diffusion du CINES, Alain Colas, directeur du GIS Collex-Pers\xe9e, Viviane Boul\xe9treau, responsable du p\xf4le informatique de Pers\xe9e. Echange anim\xe9 par Fran\xe7ois Cavalier, directeur de la biblioth\xe8que de Sciences Po Paris.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Installer NumaHOP : quelles options pour mon \xe9tablissement ?](https://www.youtube.com/watch?v=bc5OQxKiEwg) Lo\xefc Charlery, responsable des infrastructures de la biblioth\xe8que Sainte-Genevi\xe8ve, Olivier Pouchard, responsable du service \xe9tudes et d\xe9veloppements \xe0 Sciences Po Paris, Christophe Paris, chef de l\u2019\xe9quipe informatique \xe0 la BULAC. Echange anim\xe9 par St\xe9phane Auzanneau, directeur de la DSI \xe0 Sciences Po Paris.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Progilone : quelles possibilit\xe9s d\u2019h\xe9bergement ?] pr\xe9sent\xe9 par Anne Dupiat, chef de projet Progilone.\\n- <Icon icon={[\\"fa\\", \\"video\\"]} /> [Et la suite : comment structurer une communaut\xe9 NumaHOP ?](https://www.youtube.com/watch?v=HTCkc5uaOFc), par Fran\xe7ois Cavalier, directeur de la biblioth\xe8que de Sciences Po Paris, Marie-Lise Tsagouria, directeur de la BULAC et Claire Sonnefraud, responsable du d\xe9partement de la conservation \xe0 la biblioth\xe8que Sainte-Genevi\xe8ve."}]}}')}}]);